  "risk": {
    "level": "medium",
    "touches": ["rpc_api"],
    "why": "Clients relying specifically on HTTP 403 status codes rather than JSON-RPC error payloads for JSON-RPC 2.0 or batch denials may misparse responses."
  }
}
